SELECT name, r FROM (SELECT c.name, SUM(CASE WHEN CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE) > s.promised_date THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS r FROM shipments s JOIN couriers c USING (courier_id) WHERE s.delivered_at_utc IS NOT NULL AND s.order_id IN (SELECT order_id FROM orders WHERE is_deleted = FALSE) AND CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE) BETWEEN DATE '2026-07-01' AND DATE '2026-10-31' GROUP BY c.name) t ORDER BY r DESC LIMIT 1
